From: zack-vii <zack-vii@live.com>
Date: Fri, 2 Dec 2016 12:38:18 +0100
Subject: [PATCH] fixed error introduced by change made in f18f13a


diff --git a/tdishr/TdiDoTask.c b/tdishr/TdiDoTask.c
index ab962fa9d..faef8eaa3 100644
--- a/tdishr/TdiDoTask.c
+++ b/tdishr/TdiDoTask.c
@@ -85,10 +85,8 @@ STATIC_ROUTINE int Doit(struct descriptor_routine *ptask, struct descriptor_xd *
 	arglist[j] = (void *)pmethod->arguments[j - 3];
       arglist[ndesc] = (void *)out_ptr;
       arglist[ndesc + 1] = MdsEND_ARG;
-      if (status & 1) {
-        struct descriptor_s out = { sizeof(void *) , DTYPE_POINTER, CLASS_S , LibCallg(arglist, TreeDoMethod) };
-        MdsCopyDxXd((struct descriptor*)&out, out_ptr);
-      }
+      void* result = LibCallg(arglist, TreeDoMethod);
+      status = TdiPutLong((int*)&result, out_ptr);
       StrFree1Dx(&method_d);
       break;
     }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was introduced due to a change in how the result from the `LibCallg` function was being handled. The previous implementation relied on checking the status and creating a descriptor to manage the output, which could lead to incorrect handling of the result if the status was not as expected. The new implementation simplifies this process but indicates that the previous method was flawed in its approach to managing the output, potentially leading to errors in the output value being set in `out_ptr`.

        Commit message:
        fixed error introduced by change made in f18f13a  

        Patch:

 STATIC_ROUTINE int Doit(struct descriptor_routine *ptask, struct descriptor_xd *out_ptr)
 {
   int dtype, ndesc, j, status;
   void **arglist[256];
   ndesc = ptask->ndesc;
   while (ndesc > 3 && ptask->arguments[ndesc - 4] == 0)
     ndesc--;
   dtype = ptask->length ? *(unsigned char *)ptask->pointer : DTYPE_L;
   switch (ptask->dtype) {
   case DTYPE_METHOD:{
       struct descriptor_method *pmethod = (struct descriptor_method *)ptask;
       int nid;
       DESCRIPTOR_NID(nid_dsc, 0);
       struct descriptor_d method_d = { 0, DTYPE_T, CLASS_D, 0 };
       nid_dsc.pointer = (char *)&nid;
       status = TdiData(pmethod->method, &method_d MDS_END_ARG);
       if (status & 1)
 	status = TdiGetNid(pmethod->object, &nid);
       *(int*)&arglist[0] = ndesc + 1;
       arglist[1] = (void*)&nid_dsc;
       arglist[2] = (void*)&method_d;

       /*** skip timeout,method,object ***/
       for (j = 3; j < ndesc; ++j)
 	arglist[j] = (void *)pmethod->arguments[j - 3];
       arglist[ndesc] = (void *)out_ptr;
       arglist[ndesc + 1] = MdsEND_ARG;
-      if (status & 1) {
-        struct descriptor_s out = { sizeof(void *) , DTYPE_POINTER, CLASS_S , LibCallg(arglist, TreeDoMethod) };
-        MdsCopyDxXd((struct descriptor*)&out, out_ptr);
-      }
+      void* result = LibCallg(arglist, TreeDoMethod);
+      status = TdiPutLong((int*)&result, out_ptr);
       StrFree1Dx(&method_d);
       break;
     }
     /*case DTYPE_PROCEDURE :    break; */
   case DTYPE_PROGRAM:
     {
       struct descriptor_program *prog_task = (struct descriptor_program *)ptask;
       if (prog_task->program && prog_task->program->dtype == DTYPE_T)
 	status = LibSpawn(prog_task->program, 1, 0) == 0;
       status = TdiPutLong(&status, out_ptr);

     }
     break;
   case DTYPE_ROUTINE:
     status = TdiCall(dtype, ndesc - 1, &ptask->image, out_ptr);
     break;
   default:
     status = TdiINVDTYDSC;
     break;
   }
   return status;
 }



